import { translated, type Translate } from 'src/utils/translate';

export { translated };
export type { Translate };

export interface LabelledOption {
  label: string;
  value: string;
}

export const ISSUE_STATUSES = ['todo', 'in_progress', 'in_review', 'done', 'cancelled', 'error'];
export const ISSUE_PRIORITIES = ['critical', 'high', 'medium', 'low'];
export const ISSUE_TYPES = ['task', 'review', 'approval', 'escalation'];

export function titleCase(value: string): string {
  return value.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

function translateOrTitleCase(t: Translate, key: string, fallbackFrom: string): string {
  return translated(t, key, titleCase(fallbackFrom));
}

export function statusLabel(t: Translate, status: string): string {
  if (!status) return '';
  return translateOrTitleCase(t, `status_${status}`, status);
}

export function priorityLabel(t: Translate, priority: string): string {
  if (!priority) return '';
  return translateOrTitleCase(t, `priority_${priority}`, priority);
}

export function issueTypeLabel(t: Translate, type: string): string {
  if (!type) return '';
  return translateOrTitleCase(t, `issue_type_${type}`, type);
}

export function skillLabel(t: Translate, id: string): string {
  if (!id) return '';
  return translateOrTitleCase(t, `docnet_skill_${id}`, id);
}

// Skills have no id-derived description worth showing, so an untranslated one
// renders nothing rather than a placeholder.
export function skillDescription(t: Translate, id: string): string {
  if (!id) return '';
  const key = `docnet_skill_${id}_desc`;
  const translated = t(key);
  return translated && translated !== key ? translated : '';
}

const INBOX_ACTION_KEYS: Record<string, string> = {
  approve: 'approve',
  reject: 'reject',
  comment: 'comment',
};

export function inboxActionLabel(t: Translate, action: string, backendLabel: string): string {
  const key = INBOX_ACTION_KEYS[action];
  if (!key) return backendLabel;
  const translated = t(key);
  return translated && translated !== key ? translated : backendLabel;
}

function toOptions(values: string[], label: (value: string) => string): LabelledOption[] {
  return values.map((value) => ({ label: label(value), value }));
}

export function statusOptions(t: Translate, values: string[] = ISSUE_STATUSES): LabelledOption[] {
  return toOptions(values, (v) => statusLabel(t, v));
}

export function priorityOptions(t: Translate, values: string[] = ISSUE_PRIORITIES): LabelledOption[] {
  return toOptions(values, (v) => priorityLabel(t, v));
}

export function issueTypeOptions(t: Translate, values: string[] = ISSUE_TYPES): LabelledOption[] {
  return toOptions(values, (v) => issueTypeLabel(t, v));
}

export const AGENT_ROLES = ['orchestrator', 'router', 'specialist'];

export function toolLabel(t: Translate, name: string): string {
  if (!name) return '';
  return translateOrTitleCase(t, `docnet_tool_${name}`, name);
}

export function roleLabel(t: Translate, role: string): string {
  if (!role) return '';
  return translateOrTitleCase(t, `docnet_role_${role}`, role);
}

export function roleOptions(t: Translate, values: string[] = AGENT_ROLES): LabelledOption[] {
  return toOptions(values, (v) => roleLabel(t, v));
}

export interface AgentIdentity {
  name: string;
  is_system?: boolean;
}

// Display-only overlay for the agents DocBits ships. The stored name still
// drives orchestrator routing and mission filtering, so it is never mutated
// here, and an org's own agents keep whatever name the org gave them.
//
// Keyed on the English name rather than the id: `agents.id` is a UUID column
// defaulted to uuid4, so a seeded agent's id differs per deployment and
// carries no identity to key on. `is_system` is the server's own answer to
// "did DocBits ship this?", which is the question being asked.
export function agentDisplayName(
  t: Translate,
  agent: AgentIdentity | null | undefined,
): string {
  if (!agent?.name) return '';
  if (!agent.is_system) return agent.name;
  return translated(t, agentNameKey(agent.name), agent.name);
}

/** ``"DocBits Guide"`` → ``"docnet_agent_name_docbits_guide"``. */
function agentNameKey(name: string): string {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return `docnet_agent_name_${slug}`;
}
